    .elementor-location-header, header {
        display: none;
    }
    p,a{
        font-family: 'Helvetica', sans-serif;
        font-size: 18px;
    }
    p.mobile{
        display: none;
    }
    h1,h2,h3,h4,h5{
        font-family: "Lato", sans-serif;
        font-weight: 900;
        font-style: normal;
    }
    .ast-container{
        max-width: 100dvw !important;
        padding: 0 !important;

    }
    .male-template, .entry-content{
        width: 100dvw;
        display: flex;
        flex-direction: column;
        max-width: 1440px;
        margin: 0 auto;

        
        > .wp-block-group{
            max-width: 100% !important;
            margin-left: 0;
            margin-right: 0;
        }
    }

    .banner{
        position: relative;
        width: 100%;
        height: 90dvh;
        overflow: hidden;
        padding: 0 !important;
        h3{
            font-size: 30px;
            color: black;
            letter-spacing: 4px;
            line-height: 1;

            strong{
                font-size: 80px;
            }
        }
        p{
            font-size: 18px;
        }
        .wp-block-group{
            position: absolute;
            top: 50%;
            left: 10%;
            width: 45%;
            color: black;
            height: fit-content;
            transform: translateY(-50%);
            strong{
                color: #D4433B;
                font-weight: normal;
            }
        }
        
        .wp-block-image{
            position: relative;
            img{
                width: 100%;
                height: 100%;
                object-fit: cover;
            }
        }
    }
    .about{
        position: relative;
        display: grid;
