    .products{
        background-color: #312E2E;
        display: flex;
        flex-direction: column;
        gap: 1.5em;
        padding: 4em 10% !important;
        color: white;
        .wp-block-group{
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 1em;
            text-align: center;
            p{
                margin-top: 0 !important;
            }
            h2,h3,h4,h5{
                color: white;
                em{
                    font-style: normal;
                    font-weight: 400;
                }
            }

        }

        .wp-block-gallery{
            display: grid;
            grid-template-columns: 1fr 1fr 1fr 1fr;
            column-gap: 0 !important;
            row-gap: 1.5em !important;
            grid-template-rows: auto;
            overflow: hidden;
            
            .wp-block-image{
                width: 100% !important;
               
                padding: 1.5em 20%;
                
            }
            .wp-block-image:nth-child(4n+2){
                border-left: 1px solid #ffffffa4;
                border-right: .5px solid #ffffffa4;
            }
            .wp-block-image:nth-child(4n+3){
                border-left: .5px solid #ffffffa4;
                border-right: 1px solid #ffffffa4;
            }
            .wp-block-image:nth-child(n+5) {
                display: none;
            }
            img{
                width: auto;
                height: 100%;
                object-fit: contain !important;
            }
        }
        .wp-block-gallery-collapsed{
            .wp-block-image:nth-child(n+5) {
                display: flex;
            }
        }
        .btn-ver{
            margin: 0 auto;
        }
    }

    @media (max-width: 1080px) {
        .banner{
            height: 75dvh;
            .wp-block-image{
                height: 100%;
            }
           
            
        }
        .about{
            padding: 2em 1em !important;
        }
        .about2{
            .wp-block-group{
                padding: 10% 1em !important;
            }
        }
        
    }

    @media (max-width: 469px) {
        p,a{
            font-size: 14px;
        }
        p{
            display: none;
        }

        p.mobile{
            display: block;
        }

        .banner{
            height: 95dvh;
            .wp-block-group{
                width: calc(100% - 2em);
                left: 1em;
             
                h3,h2{
                    font-size: 30px;
                    strong{
                        font-size: 45px;
                        font-weight: 900;
                    }
                }
                p{
                    font-size: 14px;
                }
            }
                
            
        }

        .about{
            grid-template-columns: 1fr;
            .wp-block-group{
                width: 100%;
               
            }
            
            .wp-block-heading{
                grid-column: span 1;
                font-size: 30px;
                strong{
                    font-size: 24px;
                }
            }
            .wp-block-image{
                max-height: 50dvh;
                aspect-ratio: 1/1;
                display: flex;
                margin: 0 auto;
                img{
                   height: 100%;
                   width: auto;
                   margin: 0 auto 
                }
            }

        }

        .about2{
            display: flex;
            flex-direction: column;
            img{
                max-height: 45dvh;
            }
            .wp-block-group h2,h3{
                font-size: 30px;
                strong{
                    font-size: 24px;
                }
            }
        }

        .products{
            padding: 3em 1em !important;
            .wp-block-gallery{
                grid-template-columns: 1fr 1fr;
            }
            .wp-block-image:nth-child(4n+2){
                border-left: 0 !important;
                border-right: 0 !important;
            }
            .wp-block-image:nth-child(4n+3){
                border-left: 0 !important;
                border-right: 0 !important;
            }
            .wp-block-image:nth-child(odd){
                border-right: 1px solid #ffffffa4 !important;
            }
            

        }
      
        
    }